-- Blasted Lands: creature abilities
-- Most of the zone's creatures (the demons of the Dark Portal, the Darktail and Bloodwash, the ogres, scorpids and boars) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '1088,5974,5975,5976,5977,5978,5983,5985,5990,5996,5997,5998,6004,6005,6006,6007,6008,6009,6010,6011,8296,8297,8298,8299,8300,8301,8302,8303,14446,41133,41134,41136,41138,41158,41163,41164,41165,41166,41171,41173,41191,41253,41254,41267,41280,41386,41387,41404,41405,41422,41423,41470,41471,42228,42231,42235,42244,42248,42249,42296,42297,42334,42336,42337,42338,42359,44321,45031,45087,45118,45119,45125,45257,45258,45260,45262,51542,51791,51792';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881,41279,41290,51541';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
